#!/usr/bin/env python3
"""Create a bounded, entirely synthetic FICTION evaluation research corpus.
No API calls, no editor integration, no private manuscripts, no claim of model evaluation.
"""
import json
from pathlib import Path
root=Path(__file__).resolve().parent

def c(id,genre,pov,chronology,task,setup,prompt,passage,canon,checks,exception="None",profile=""):
    return dict(id=id,origin="synthetic-original-research-fixture",genre=genre,pov=pov,chronology=chronology,task=task,author_goal=prompt,story_context=setup,source_passage=passage,approved_facts=canon,deliberate_exception=exception,expected_human_review_checks=checks,profile_review_target=profile,model_outputs=[],human_ratings=[])

cases=[
c("VL4-01","secondary-world fantasy","third limited","linear","continue","Iris fractured her left wrist the previous evening; her sword is too heavy for one-handed combat.","Continue the escape using a plausible distraction, preserving immediacy and physical consequence.","Iris drew her blade half an inch, then stopped. Pain traveled up her left wrist. Two guards watched the stairwell.",["Iris left wrist fractured","Iris cannot effectively swing the two-handed sword"],["No impossible two-hand sword technique","POV reports only what Iris can know","Physical actions follow from injury"]),
c("VL4-02","cozy mystery","first person unreliable","nonlinear flashback","rewrite","The narrator has concealed a missing hour; the reader must notice evasiveness, not receive an explicit confession.","Rewrite the account to reduce repetitive explanations without making the narrator honest.","I told them I left at nine. That was my answer. Anyone could have seen me leave then, had they been looking at the correct clock.",["Narrator has not admitted the lost hour","A wall clock runs fifteen minutes slow"],["Unreliable ambiguity preserved","No invented confession","First-person voice remains selective"],"Deliberate evasiveness is appropriate"),
c("VL4-03","romance","third limited","linear","continue","Ex-partners work together during a flood; a previous apology did not resolve the core betrayal.","Continue the tense boat-repair scene without rushing emotional closure.","Nadia held the lantern. Tomas said, 'You still don't trust me.' She passed him the wrench without answering.",["They separated after a betrayal","Nadia accepted an apology but did not restore trust"],["Tension may persist","No immediate reconciliation without cause","Each character has an independent goal"]),
c("VL4-04","science fiction","second person","linear","continue","You are a cargo engineer; another crew member secretly knows a transmission was forged.","Continue from your limited knowledge without revealing the forgery.","You trace the static with one finger. The numbers match the manifest, and that should make you less afraid.",["You have not learned the signal was forged","Only the navigator knows about the forgery"],["No secret leaks to viewpoint","Second-person perspective maintained","Scientific detail arises from established expertise"]),
c("VL4-05","progression fantasy","third limited","linear","continue","Kei can absorb heat but cannot release it outside their body. Previous training left the core unstable.","Continue a training mishap, honoring power costs and causality.","The furnace clicked. Kei reached for the heat and felt the core shiver before the metal warmed.",["Kei can absorb but not externalize heat","Core destabilizes under excessive absorption"],["No unearned new power","Cost/consequences accumulate","Progress follows learning rather than convenient upgrade"]),
c("VL4-06","literary fiction","first person","associative recollection","rewrite","The narrator uses regional cadence, sentence fragments and weather details to avoid grief.","Improve clarity without homogenizing deliberate cadence.","My aunt's porch. All them boards clicking, click-click. Rain made the road look like somebody had rubbed the chalk clean off.",["Narrator avoids naming grief directly"],["Regional cadence retained","Fragments preserved when functional","Meaning not overexplained"],"Nonstandard grammar and fragments are author-approved voice"),
c("VL4-07","psychological horror","third limited","ambiguous chronology","continue","A hallway repeatedly appears a few steps longer. The author wants uncertainty about the cause.","Continue the scene with concrete perception, without explaining the supernatural mechanism.","At the third door, Lio stopped counting. The wallpaper seam should have been behind him.",["Hallway anomaly is not yet explained"],["Mystery remains unresolved","No arbitrary exposition","Sensory specificity without explanation"],"Unresolved supernatural ambiguity is intentional"),
c("VL4-08","satirical comedy","omniscient","linear","rewrite","The narrator deliberately uses rhetorical triplets to parody a bureaucratic announcement.","Sharpen comedic rhythm without deleting all repeated patterns.","The Department promised efficiency, transparency, and accountability. The Department delivered a form, a queue, and another form.",["Department bureaucracy is central satire"],["Triplet form retained if serving joke","Repetition judged by comic function","No imposed sincerity"],"Parallel triplets are an intentional structural gag"),
c("VL4-09","invented historical fiction","third limited","flashback","continue","Two chapters ago a court scribe hid a sealed treaty; current scene occurs eight years earlier.","Continue the flashback without referencing later events as already known.","At sixteen, Sela regarded the unopened treaty with the suspicion reserved for other people's homework.",["Treaty hidden eight years after this scene","Sela is sixteen in flashback"],["No future knowledge leakage","Age and chronology respected","No modern anachronism inserted without intent"]),
c("VL4-10","web serial adventure","alternating limited POV","linear","continue","Chapter A follows a hunter; Chapter B follows a healer. They hold opposing interpretations of a missing caravan.","Continue the hunter POV only, keeping conflicting knowledge separate.","Rokan turned over the broken wheel. He did not know whether the healer had arrived ahead of him.",["Hunter believes caravan was robbed","Healer suspects voluntary disappearance","Hunter has not heard healer's suspicion"],["Distinct epistemic boundaries","No POV leakage","Progression without repeating prior quest beat"]),
c("VL4-11","political fantasy","third limited","linear","rewrite","The protagonist can be morally compromised; narrator does not deliver a closing lesson.","Rewrite a victory scene to preserve moral ambiguity and political costs.","The council cheered when the levy passed. Behind the hall, the bakers counted how much flour they could no longer afford.",["Tax levy secures defense","Levy harms the poor"],["Competing consequences remain visible","No didactic certainty","No forced moral summary"],"Competing interpretations intentionally unresolved"),
c("VL4-12","space opera","third limited","multi-book isolation","continue","Synthetic Project A calls its navigator Iven; separate Project B has another Iven with unrelated history.","Continue Project B without inheriting Project A facts or custom style settings.","Iven checked the airlock gauge. The captain had never trusted him with the cargo code.",["Project B Iven is a ship mechanic","Project A Iven is a court astrologer","No shared story universe"],["No cross-project facts","No cross-project rule carryover","Model context sources documented"]),
c("VL4-13","urban fantasy","third limited","long horizon / late reveal","continue","Chapter 60 resolves the mystery of a silver key first introduced in chapter 3. Writer has kept two deliberate false leads.","Outline an earned discovery without inventing an earlier revelation.","Amal placed the key in the lock, then stopped. She remembered the mark on the door from the first winter.",["Silver key seen in chapter 3","Red envelope false lead rejected chapter 30","Door mark recorded chapter 2"],["Earlier promises paid off","False leads not forgotten","Chronology consistent","Source facts bounded, not entire 60-chapter dump"]),
c("VL4-14","quiet contemporary drama","first person","linear","rewrite","The author selected two marked paragraphs for a restrained rewrite; a later live edit changes the selected text during request.","Generate a proposal only; never silently apply against a changed selection.","At first I tried to call. Then I folded the phone into the drawer and told myself that was enough.",["Selected text revision hash changes while request in flight"],["Proposal remains pending","Source-version mismatch requires review","Other paragraphs unmodified","Author can reject or undo"])
]
with (root/'R19_SYNTHETIC_FICTION_CORPUS_v0.1.jsonl').open('w',encoding='utf8') as f:
 for v in cases:f.write(json.dumps(v,ensure_ascii=False)+'\n')

edits=[
 ('RE10-01','unchanged exact range, same chapter revision','allow_after_author_accept','accept only selected normalized Tiptap slice; one transaction'),
 ('RE10-02','author edited target while AI was streaming','block_and_repreview','revision or selection content hash mismatch; never replace new prose'),
 ('RE10-03','author changed unrelated paragraph before response','review_or_safe_rebase','conservative CAS blocks; if step mapping used, remapped target and structural hash must match'),
 ('RE10-04','author changed bold/italic marks in selection','block_and_repreview','structural node+mark hash differs despite same plain text'),
 ('RE10-05','author split target paragraph into two','block_and_repreview','old numeric offset invalid; do not search-and-replace first text match'),
 ('RE10-06','two proposals overlap same original selected text','serialize_or_rebase_after_review','only first can apply; second must be revalidated'),
 ('RE10-07','AI request canceled while streaming','no_manuscript_mutation','cancel is idempotent; ignore late completion'),
 ('RE10-08','user rejects proposal','no_manuscript_mutation','accepted chapter and canon byte/structural hashes unchanged'),
 ('RE10-09','user accepts prose but rejects profile delta','text_only_mutation','profile canon unchanged; independent review decisions'),
 ('RE10-10','user clicks accept twice, or retry after timeout','idempotent_accept','only one accepted revision/transaction; duplicate harmless'),
 ('RE10-11','suggestion includes HTML/script or unsupported marks','block_and_repreview','sanitize or reject invalid schema; no raw script injection'),
 ('RE10-12','browser local undo after accepted server save','requires_revisioned_compensation','editor undo must be saved as new authorized revision, not assumed durable rollback'),
 ('RE10-13','rewrite would replace another book with same phrase','block_cross_book','scope includes authenticated author/book/chapter IDs not raw text matching'),
 ('RE10-14','AI output is partial due 429 mid-stream','no_manuscript_mutation','partial output never auto-promoted; clear error/partial state'),
 ('RE10-15','AI returns suggested change from unaccepted generated passage','proposal_only','derived canon remains unapproved even if manuscript proposal accepted later'),
]
with (root/'R10_REVERSIBLE_EDIT_CASES_v0.1.jsonl').open('w',encoding='utf8') as f:
 for id,scenario,policy,invariant in edits:f.write(json.dumps(dict(id=id,scenario=scenario,expected_control=policy,expected_invariant=invariant,status='NOT_RUN',implementation='none; research fixture only'),ensure_ascii=False)+'\n')
print('created',len(cases),'fiction cases and',len(edits),'editor cases')
